-- LA addendum: Santa Monica Beach pre-existed below the harvest's beach bar
-- (scope regional, pop 935) — the founder named it a top destination; raise it.
UPDATE attractions SET popularity=MAX(COALESCE(popularity,0),2000000), scope=CASE WHEN scope IN ('local','regional','') OR scope IS NULL THEN 'national' ELSE scope END, updated_at=datetime('now') WHERE id='wikidata:Q7419811';
-- Dedupe true twins (same name, same country, within ~2 km — 775 pairs found
-- 2026-10-06, e.g. the two Santa Monica Pier rows): AFTER the boosts above,
-- keep the more popular twin, delete the weaker; ties keep the smaller id.
DELETE FROM attractions WHERE id IN (
  SELECT b.id FROM attractions a JOIN attractions b
    ON a.name=b.name AND a.country=b.country AND a.id != b.id
   AND ABS(a.lat-b.lat)<0.02 AND ABS(a.lng-b.lng)<0.02
  WHERE COALESCE(a.popularity,0) > COALESCE(b.popularity,0)
     OR (COALESCE(a.popularity,0) = COALESCE(b.popularity,0) AND a.id < b.id)
);
